---刷新cell
---@param data table
---@param selectedNum integer 选中数量
---@param isMax boolean 卡牌是否升满
---@param addFunc  function cell点击回调
---@param reduceFunc  function 减少按钮点击回调
---@param lockFunc function 锁定按钮点击回调
---@param index integer 序号
function GroceryCoreExchangeListCell:RefreshCell(data, selectedNum, isMax, addFunc, reduceFunc, lockFunc, index)
    local scr = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    if isNotNull(scr) then
        scr:Reload({ goodsId = data.goodsId, isShowNo = true, text = data.num})
    end
    self._addFunc = addFunc
    self._reduceFunc = reduceFunc
    self._lockFunc = lockFunc
    self._index = index
    CfUtils.SetActive(self.OverflowMax, checkBool(isMax))
    local backpackComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local lock = backpackComp:IsGoodsLocked(data.goodsId)
    CfUtils.SetUISwitchImage(self.LockImgIcon, lock and 1 or 2)
    CfUtils.SetUISwitchImage(self.LockImgBg, lock and 1 or 2)
    self:SetSelectedNum(selectedNum)
end

---设置选中数量
---@param selectedNum integer  选中数量
function GroceryCoreExchangeListCell:SetSelectedNum(selectedNum)
    local num = checkInt(selectedNum)
    if num > 0 then
        GameUtils.UpdateUIShowStateByCanvasGroup(self.NumberNode, true)
        CfUtils.SetActive(self.BtnLock, false)
        CfUtils.FillText(self.TxtPlusNumber, num)
    else
        GameUtils.UpdateUIShowStateByCanvasGroup(self.NumberNode, false)
        CfUtils.SetActive(self.BtnLock, true)
    end
end
--endregion public

